// Minimal Edge Function that works with the legacy anon / service_role keys
// generated by this template (the upstream `hello` example expects the newer
// sb_publishable_/sb_secret_ keys).
//
// curl http://127.0.0.1:58000/functions/v1/ping -H "Authorization: Bearer $ANON_KEY"

export default {
  fetch(_req: Request): Response {
    return Response.json({ message: "pong", time: new Date().toISOString() })
  },
}
